import React from "react";
import { useCurrentFrame, useVideoConfig, AbsoluteFill, interpolate, spring } from '../remotionShim';
{/* Start Google Fonts Loader */ }
const useFontLoader = (fonts: string[]) => {
  const stableFonts = React.useMemo(() => {
    const unique = [...new Set(fonts.map(f => f.trim()))].sort();
    return unique;
  }, [fonts.join("|")]);

  React.useEffect(() => {
    const unloaded = stableFonts.filter(
      (font) =>
        !document.querySelector(
          `link[href*="${font.replace(/\s+/g, "+")}"]`
        )
    );

    if (unloaded.length === 0) return;

    const url = `https://fonts.googleapis.com/css2?${unloaded
      .map((font) => `family=${font.replace(/\s+/g, "+")}:wght@400;500;600`)
      .join("&")}&display=swap`;

    const link = document.createElement("link");
    link.rel = "stylesheet";
    link.href = url;

    document.head.appendChild(link);
  }, [stableFonts]);
};
{/* End Google Fonts Loader */ }



export type AppleBrowserZoomProps = Record<string, any>;

const AppleBrowserZoom: React.FC<AppleBrowserZoomProps> = ({
  backgroundColor = "#F3F4F6",
  transparentBackground = false,
  durationInSeconds = 6,
  url = "google.com",
  browserTheme = "light",
  zoomIntensity = 3,
  startDelay = 15,
  finalHorizontalOffset = 0,
}) => {
  useFontLoader(["Inter"]);

  const frame = useCurrentFrame();
  const { fps, width } = useVideoConfig();

  // --- Configuration ---
  const isDark = browserTheme === "dark";
  const theme = {
    windowBg: isDark ? "#1E1E1E" : "#FFFFFF",
    borderColor: isDark ? "#333333" : "#E5E5E5",
    addressBarBg: isDark ? "#2C2C2C" : "#F1F3F4",
    textColor: isDark ? "#E0E0E0" : "#202124",
    trafficStroke: isDark ? "rgba(255,255,255,0.1)" : "rgba(0,0,0,0.1)",
    shadow: isDark
      ? "0 40px 80px rgba(0,0,0,0.5)"
      : "0 40px 80px rgba(0,0,0,0.15)",
  };

  const bgColor = transparentBackground ? "transparent" : backgroundColor;

  // --- Animation Timing ---
  const zoomStartFrame = startDelay;
  const zoomDuration = 45;
  
  const typingStartFrame = zoomStartFrame + 20;
  const typingDuration = Math.max(30, url.length * 3);

  // --- Animations ---
  
  // 1. Zoom Spring
  const zoomSpring = spring({
    frame: frame - zoomStartFrame,
    fps,
    config: {
      damping: 200,
      stiffness: 100,
      mass: 2,
    },
  });

  const scale = interpolate(zoomSpring, [0, 1], [1, zoomIntensity]);
  const translateY = interpolate(zoomSpring, [0, 1], [0, 150]);
  const translateX = interpolate(zoomSpring, [0, 1], [0, finalHorizontalOffset]);

  // 2. Typing Progress
  const typingProgress = interpolate(
    frame,
    [typingStartFrame, typingStartFrame + typingDuration],
    [0, 1],
    { extrapolateLeft: "clamp", extrapolateRight: "clamp" }
  );

  const charIndex = Math.round(typingProgress * url.length);
  const currentText = url.substring(0, charIndex);

  // 3. Cursor Blinking
  const cursorOpacity = Math.sin(frame / 5) > 0 ? 1 : 0;
  const showCursor = frame > typingStartFrame && frame < typingStartFrame + typingDuration + 60;

  // --- Dimensions ---
  const browserWidth = Math.min(width * 0.8, 1200);
  const browserHeight = browserWidth * 0.65;
  const headerHeight = 50;

  return (
    <AbsoluteFill
      style={{
        backgroundColor: bgColor,
        justifyContent: "center",
        alignItems: "center",
        fontFamily: "Inter, sans-serif",
        perspective: "1000px",
      }}
    >
      {/* Zoom Container */}
      <div
        style={{
          width: browserWidth,
          height: browserHeight,
          transform: `scale(${scale}) translate(${translateX}px, ${translateY}px)`,
          transformOrigin: "25% 15%", 
          willChange: "transform",
        }}
      >
        {/* Browser Window */}
        <div
          style={{
            width: "100%",
            height: "100%",
            backgroundColor: theme.windowBg,
            borderRadius: 12,
            boxShadow: theme.shadow,
            display: "flex",
            flexDirection: "column",
            overflow: "hidden",
            border: `1px solid ${theme.borderColor}`,
          }}
        >
          {/* Header / Toolbar */}
          <div
            style={{
              height: headerHeight,
              width: "100%",
              display: "flex",
              alignItems: "center",
              padding: "0 20px",
              gap: 20,
              borderBottom: `1px solid ${theme.borderColor}`,
            }}
          >
            {/* Traffic Lights */}
            <div style={{ display: "flex", gap: 8 }}>
              <div style={{ width: 12, height: 12, borderRadius: "50%", backgroundColor: "#FF5F56", border: `1px solid ${theme.trafficStroke}` }} />
              <div style={{ width: 12, height: 12, borderRadius: "50%", backgroundColor: "#FFBD2E", border: `1px solid ${theme.trafficStroke}` }} />
              <div style={{ width: 12, height: 12, borderRadius: "50%", backgroundColor: "#27C93F", border: `1px solid ${theme.trafficStroke}` }} />
            </div>

            {/* Address Bar */}
            <div
              style={{
                flex: 1,
                height: 32,
                backgroundColor: theme.addressBarBg,
                borderRadius: 8,
                display: "flex",
                alignItems: "center",
                padding: "0 12px",
                gap: 10,
                fontSize: 14,
                color: theme.textColor,
                position: "relative",
              }}
            >
              {/* Lock Icon */}
              <svg
                width="12"
                height="12"
                viewBox="0 0 24 24"
                fill="none"
                stroke="currentColor"
                strokeWidth="3"
                strokeLinecap="round"
                strokeLinejoin="round"
                style={{ opacity: 0.6 }}
              >
                <rect x="3" y="11" width="18" height="11" rx="2" ry="2" />
                <path d="M7 11V7a5 5 0 0 1 10 0v4" />
              </svg>

              {/* URL Text */}
              <div style={{ display: "flex", alignItems: "center" }}>
                <span>{currentText}</span>
                {showCursor && (
                  <span
                    style={{
                      opacity: cursorOpacity,
                      marginLeft: 1,
                      width: 2,
                      height: 16,
                      backgroundColor: theme.textColor,
                      display: "block",
                    }}
                  />
                )}
              </div>
            </div>
          </div>

          {/* Browser Body (Placeholder content) */}
          <div
            style={{
              flex: 1,
              backgroundColor: isDark ? "#121212" : "#FFFFFF",
              position: "relative",
              overflow: "hidden",
            }}
          >
            {/* Simulated Content Skeleton */}
            <div
              style={{
                padding: "40px 60px",
                display: "flex",
                flexDirection: "column",
                gap: 20,
                opacity: 0.3,
              }}
            >
              <div style={{ width: "40%", height: 32, borderRadius: 4, backgroundColor: theme.textColor }} />
              <div style={{ width: "100%", height: 200, borderRadius: 8, backgroundColor: theme.addressBarBg }} />
              <div style={{ width: "80%", height: 16, borderRadius: 4, backgroundColor: theme.textColor }} />
              <div style={{ width: "90%", height: 16, borderRadius: 4, backgroundColor: theme.textColor }} />
              <div style={{ width: "70%", height: 16, borderRadius: 4, backgroundColor: theme.textColor }} />
            </div>
          </div>
        </div>
      </div>
    </AbsoluteFill>
  );
};

export default AppleBrowserZoom;